<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
require_once dirname(__DIR__).'/app/Auth/SessionUser.php';require_once dirname(__DIR__).'/app/UI/Workspace.php';
require_once dirname(__DIR__).'/app/Mail/PersonalAccounts.php';require_once dirname(__DIR__).'/app/Mail/SpamPolicy.php';require_once dirname(__DIR__).'/app/Mail/Mailboxes.php';require_once dirname(__DIR__).'/app/Mail/ServerProfiles.php';
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: default-src 'self'; style-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");
tnl_session();$db=tnl_db();$identity=\TNL\Auth\SessionUser::require($db);
$store=new \TNL\Mail\ExternalAccount($db,tnl_path('storage'));$personal=new \TNL\Mail\PersonalAccounts($db,$store);$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 tnl_check_csrf();
 try{
  $action=(string)($_POST['action']??'');
  if($action==='logout'){$_SESSION=[];session_regenerate_id(true);header('Location: index.php');exit;}
  if($action==='name'&&$identity['role']==='employee'){
   $name=trim((string)($_POST['display_name']??''));if(strlen($name)<2||strlen($name)>100)throw new InvalidArgumentException('Nombre inválido.');
   $db->prepare('UPDATE users SET display_name=? WHERE id=?')->execute([$name,$identity['id']]);$_SESSION['employee_name']=$name;$identity['name']=$name;$notice='Perfil guardado.';
  }elseif($action==='save_account'){
   $config=\TNL\Mail\ServerProfiles::configure($db,$_POST);$new=$personal->save((int)($_POST['personal_id']??0),$identity['principal'],(string)($_POST['label']??''),$config,(string)($_POST['password']??''));
   unset($_SESSION['external_compose_tokens']);header('Location: external.php?as='.$identity['role'].'&personal='.$new.'&view=inbox');exit;
  }elseif($action==='unblock'){(new \TNL\Mail\SpamPolicy($db))->unblock($identity['principal'],(string)($_POST['sender']??''));$notice='Remitente desbloqueado.';
  }elseif($action==='remove'){
   if(!password_verify((string)($_POST['current_password']??''),$identity['user']['password_hash']))throw new InvalidArgumentException('Contraseña de TNL Mail incorrecta.');
   if(empty($_POST['confirm']))throw new InvalidArgumentException('Confirma que quieres desvincular esta cuenta.');
   $personal->remove((int)($_POST['personal_id']??0),$identity['principal']);unset($_SESSION['external_compose_tokens']);$notice='Cuenta desvinculada de TNL Mail. No se eliminó el buzón del proveedor.';
  }
 }catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'No se pudo guardar la cuenta. Revisa la configuración.';}
}
$accounts=[];$assigned=$identity['role']==='employee'?(new \TNL\Mail\Mailboxes($db))->listFor($identity['id']):[];
try{
 $legacy=$store->load($identity['principal']);if($legacy)$accounts[]=['id'=>0,'label'=>'Cuenta principal conectada','config'=>$legacy,'corporate'=>\TNL\Mail\PersonalAccounts::corporate($db,$legacy['email'])];
 foreach($personal->list($identity['principal']) as $a){$config=$store->load('personal:'.$a['id']);if($config)$accounts[]=$a+['config'=>$config,'corporate'=>\TNL\Mail\PersonalAccounts::corporate($db,$config['email'])];}
}catch(Throwable $e){$error='No se pudieron cargar todas las cuentas. Conserva la clave de credenciales junto a la base de datos.';}
$editing=(int)($_GET['edit']??0);$edit=[];$label='';
if($editing>0){try{$edit=$store->load($personal->owner($editing,$identity['principal']))??[];foreach($personal->list($identity['principal']) as $a)if((int)$a['id']===$editing)$label=$a['label'];}catch(Throwable $e){http_response_code(403);exit('Cuenta no disponible.');}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/app.css?v=0.10.0"><script src="assets/workspace.js?v=0.10.0" defer></script><title>Mi perfil · TNL Mail</title></head><body><div class="layout"><?php \TNL\UI\Workspace::sidebar($identity['role'],'profile',$identity['name']);?><main class="main"><header class="page-header"><div><span class="eyebrow">TU CUENTA</span><h1>Mi perfil</h1><p>Tu identidad, tus buzones y tu seguridad.</p></div><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><button name="action" value="logout">Cerrar sesión</button></form></header>
<?php if($error):?><p class="error"><?=tnl_escape($error)?></p><?php endif;?><?php if($notice):?><p class="notice"><?=tnl_escape($notice)?></p><?php endif;?>
<section class="panel"><h2><?=tnl_escape($identity['name'])?></h2><p><?=tnl_escape($identity['user']['internal_address']??$identity['user']['username'])?></p><p>La cuenta empresarial y las cuentas asignadas por administración no se pueden eliminar desde este menú.</p>
<?php if($identity['role']==='employee'):?><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="action" value="name"><label>Nombre visible<input name="display_name" required maxlength="100" value="<?=tnl_escape($identity['name'])?>"></label><button>Guardar perfil</button></form><?php endif;?><p><a href="recovery.php">Contraseña y recuperación</a> · <a href="lock.php">Bloqueo del dispositivo</a></p></section>
<section class="panel"><h2>Mis cuentas externas</h2>
<?php foreach($assigned as $a):?><article class="card"><h3><?=tnl_escape($a['label'])?></h3><p>Cuenta asignada por la empresa · protegida</p><a class="button button-secondary" href="external.php?as=employee&amp;box=<?=(int)$a['id']?>">Abrir buzón</a></article><?php endforeach;?>
<?php foreach($accounts as $a):?><article class="card"><h3><?=tnl_escape($a['label'])?></h3><p><?=tnl_escape($a['config']['email'])?></p><p><?=$a['corporate']?'Cuenta empresarial protegida':'Cuenta personal asociada'?></p><div class="page-actions"><a class="button button-secondary" href="external.php?as=<?=tnl_escape($identity['role'])?>&amp;<?=$a['id']?'personal='.(int)$a['id']:'box=0'?>">Abrir</a><?php if($a['id']&&!$a['corporate']):?><a href="?edit=<?=(int)$a['id']?>">Editar configuración</a><?php elseif(!$a['id']):?><a href="external.php?as=<?=tnl_escape($identity['role'])?>&amp;box=0&amp;view=account">Configuración</a><?php endif;?></div>
<?php if(!$a['corporate']):?><details><summary>Desvincular cuenta</summary><p>Quita la conexión y su contraseña guardada en TNL Mail. El buzón del proveedor y las copias conservadas para recuperación no se eliminan.</p><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="personal_id" value="<?=(int)$a['id']?>"><label>Contraseña de TNL Mail<input type="password" name="current_password" required autocomplete="current-password"></label><label><input type="checkbox" name="confirm" value="1" required> Quiero desvincular esta cuenta</label><button class="button-danger">Desvincular cuenta</button></form></details><?php endif;?></article><?php endforeach;?></section>
<section class="panel"><h2>Remitentes bloqueados</h2><?php foreach((new \TNL\Mail\SpamPolicy($db))->all($identity['principal']) as $rule):?><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="action" value="unblock"><input type="hidden" name="sender" value="<?=tnl_escape($rule['sender'])?>"><span><?=tnl_escape($rule['sender'])?></span> <button>Desbloquear</button></form><?php endforeach;?></section><section class="panel"><h2><?=$editing?'Editar cuenta externa':'Asociar otra cuenta externa'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="action" value="save_account"><input type="hidden" name="personal_id" value="<?=$editing?>">
<label>Nombre de esta cuenta<input name="label" maxlength="100" required value="<?=tnl_escape($label)?>" placeholder="Personal, proyecto…"></label><label>Dirección de correo<input type="email" name="email" required data-provider-email value="<?=tnl_escape($edit['email']??'')?>"></label><label>Configuración<select name="setup_mode" data-provider-mode><option value="auto" <?=$edit?'':'selected'?>>Automática</option><option value="manual" <?=$edit?'selected':''?>>Avanzada</option></select></label><p data-provider-status role="status"></p><details data-provider-fields <?=$edit?'open':''?>><summary>Servidores y opciones avanzadas</summary><label>Servidor IMAP 993<input name="imap_host" value="<?=tnl_escape($edit['imap_host']??'')?>"></label><label>Servidor SMTP<input name="smtp_host" value="<?=tnl_escape($edit['smtp_host']??'')?>"></label><label>Seguridad SMTP<select name="smtp_port"><option value="465">SSL/TLS 465</option><option value="587" <?=($edit['smtp_port']??465)===587?'selected':''?>>STARTTLS 587</option></select></label><label>Usuario IMAP<input name="imap_username" value="<?=tnl_escape($edit['imap_username']??'')?>"></label><label>Usuario SMTP<input name="smtp_username" value="<?=tnl_escape($edit['smtp_username']??'')?>"></label><label>Contraseña SMTP distinta<input type="password" name="smtp_password" autocomplete="new-password"></label></details><label>Contraseña del buzón<input type="password" name="password" autocomplete="new-password" <?=$edit?'':'required'?> placeholder="<?=$edit?'Vacío conserva la guardada':''?>"></label><button>Guardar y abrir cuenta</button><?php if($editing):?><a href="profile.php">Asociar otra cuenta</a><?php endif;?></form></section></main></div></body></html>
